contracts/ClusterContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title  ClusterContract
 * @notice Hierarchical PSO cluster aggregator sitting between Node contracts and the
 *         GlobalContract.  Each cluster manages a set of prosumer Nodes as its
 *         neighbourhood swarm.  After every PSO iteration the cluster:
 *
 *   1. Aggregates the per-node best positions into a weighted-average
 *      intra-cluster plan  (clusterBestPlan).
 *   2. Propagates the aggregated result up to the parent GlobalContract so the
 *      network-wide optimisation can proceed.
 *
 * Benefits over flat PSO
 * ──────────────────────
 * • Decentralised: each cluster optimises independently; only the summary is
 *   sent to the global level, reducing on-chain communication.
 * • Neighbourhood-best: nodes use the cluster best plan as their social guide
 *   (c2 term) instead of the full network-wide plan, which improves exploration
 *   diversity and avoids premature convergence.
 * • Scalable: adding more clusters adds no extra work to the GlobalContract.
 *
 * TDM compatibility
 * ─────────────────
 * ClusterContract is fully compatible with the TDM-enabled Node contracts;
 * the cluster plan it produces is already time-slot-aware because it is built
 * from TDM-optimised node positions.
 */

/* ── Interface for the parent GlobalContract ───────────────────────────────── */
interface IGlobalContract {
    function updateNodeResult(
        int[]  calldata newPosition,
        int    newScore,
        uint[] calldata newFlexibilityWeight
    ) external;
    function getBestGlobalPlan() external view returns (int[] memory);
    function getLastUpdatedTimestamp() external view returns (uint);
    function frozenGlobalCost() external view returns (int);
}

contract ClusterContract {

    // ── Storage ──────────────────────────────────────────────────────────────

    struct NodeResult {
        int[]  bestPosition;
        int    bestScore;
        uint[] flexibilityWeight;
        bool   exists;
    }

    /// @notice Parent GlobalContract reference.
    IGlobalContract public globalContract;

    /// @notice Node results keyed by node address.
    mapping(address => NodeResult) public nodeResults;
    address[] public nodeAddresses;

    /// @notice Number of time slots (set on first updateNodeResult call).
    uint public numHours;

    /// @notice Current iteration weighted-average plan.
    mapping(uint => int) public clusterOptimalPlan;

    /// @notice Best cluster plan seen across all iterations.
    int[] public clusterBestPlan;

    /// @notice Aggregate cost of all nodes' personal bests at the best iteration.
    int public clusterBestCost = type(int).max;

    /// @notice Timestamp of the last computeClusterPlan call.
    uint public lastUpdatedTimestamp;

    // ── Events ────────────────────────────────────────────────────────────────

    event NodeRegistered(address indexed node);
    event ClusterResultUpdated(address indexed node, int score);
    event ClusterPlanComputed(
        address indexed trigger,
        int[]   plan,
        uint    timestamp
    );

    // ── Constructor ───────────────────────────────────────────────────────────

    /**
     * @param _globalContract Address of the deployed GlobalContract.
     */
    constructor(address _globalContract) {
        require(_globalContract != address(0), "Invalid global contract address");
        globalContract = IGlobalContract(_globalContract);
    }

    // ── Node-facing interface (mirrors GlobalContract) ────────────────────────

    /**
     * @notice Called by each Node to push its personal-best result into the cluster.
     *
     * @dev The signature is intentionally identical to GlobalContract.updateNodeResult
     *      so Node contracts can point their `clusterContract` reference at this
     *      contract without any interface change.
     *
     * @param newPosition         Node's current best consumption plan (one value per hour).
     * @param newScore            Objective-function value of that plan.
     * @param newFlexibilityWeight Per-hour flexibility weight used for the weighted average.
     */
    function updateNodeResult(
        int[]  calldata newPosition,
        int    newScore,
        uint[] calldata newFlexibilityWeight
    ) external {
        if (!nodeResults[msg.sender].exists) {
            nodeResults[msg.sender] = NodeResult(
                newPosition,
                newScore,
                newFlexibilityWeight,
                true
            );
            nodeAddresses.push(msg.sender);
            emit NodeRegistered(msg.sender);
        } else {
            // Only update if the new score is strictly better.
            if (newScore < nodeResults[msg.sender].bestScore) {
                nodeResults[msg.sender].bestScore         = newScore;
                nodeResults[msg.sender].bestPosition      = newPosition;
                nodeResults[msg.sender].flexibilityWeight = newFlexibilityWeight;
            }
        }

        if (numHours == 0) {
            numHours = newPosition.length;
        } else {
            require(newPosition.length == numHours, "Position length mismatch");
        }

        emit ClusterResultUpdated(msg.sender, newScore);
    }

    // ── Cluster aggregation ───────────────────────────────────────────────────

    /**
     * @notice Computes the intra-cluster weighted-average optimal plan, keeps the
     *         best plan seen so far, and propagates the aggregated result up to the
     *         parent GlobalContract.
     *
     *         Call order in the PSO loop:
     *           1. All nodes call updateBestPositions()  (→ updateNodeResult here)
     *           2. ClusterContract.computeClusterPlan()  (this function)
     *           3. GlobalContract.computeGlobalOptimalPlan()
     *           4. All nodes call updateVelocityAndPosition()
     */
    function computeClusterPlan() external {
        require(nodeAddresses.length > 0, "No nodes registered in cluster");
        require(numHours > 0, "numHours not set");

        // ── Step 1: weighted-average plan across cluster nodes ────────────────
        for (uint i = 0; i < numHours; i++) {
            int  weightedSum = 0;
            uint totalWeight = 0;
            for (uint j = 0; j < nodeAddresses.length; j++) {
                NodeResult storage nr = nodeResults[nodeAddresses[j]];
                if (nr.exists) {
                    uint wt = nr.flexibilityWeight[i];
                    weightedSum += int(wt) * nr.bestPosition[i];
                    totalWeight += wt;
                }
            }
            clusterOptimalPlan[i] = (totalWeight > 0)
                ? weightedSum / int(totalWeight)
                : int(5); // default fallback
        }

        // ── Step 2: sum of node personal-best scores = cluster cost ───────────
        int currentClusterCost = 0;
        for (uint j = 0; j < nodeAddresses.length; j++) {
            if (nodeResults[nodeAddresses[j]].exists) {
                currentClusterCost += nodeResults[nodeAddresses[j]].bestScore;
            }
        }

        // ── Step 3: update clusterBestPlan if improved ────────────────────────
        if (clusterBestPlan.length == 0 || currentClusterCost < clusterBestCost) {
            clusterBestCost = currentClusterCost;
            if (clusterBestPlan.length != numHours) {
                clusterBestPlan = new int[](numHours);
            }
            for (uint i = 0; i < numHours; i++) {
                clusterBestPlan[i] = clusterOptimalPlan[i];
            }
        }

        lastUpdatedTimestamp = block.timestamp;
        emit ClusterPlanComputed(msg.sender, clusterBestPlan, lastUpdatedTimestamp);

        // ── Step 4: propagate aggregated result to GlobalContract ─────────────
        // The cluster reports itself as a single "super-node" to the global level.
        uint[] memory avgWeights = _computeAggregateWeights();
        globalContract.updateNodeResult(clusterBestPlan, currentClusterCost, avgWeights);
    }

    // ── Read helpers ──────────────────────────────────────────────────────────

    /**
     * @notice Returns the best cluster plan for use as the PSO social (neighbourhood) guide
     *         in the velocity update of each Node.
     */
    function getClusterBestPlan() external view returns (int[] memory) {
        return clusterBestPlan;
    }

    /**
     * @notice Forwards the network-wide best plan from GlobalContract.
     *         Used by Node contracts for global-deviation penalty calculation.
     */
    function getBestGlobalPlan() external view returns (int[] memory) {
        return globalContract.getBestGlobalPlan();
    }

    /**
     * @notice Returns the timestamp of the last computeClusterPlan call.
     *         Nodes can use this to check whether a fresh cluster plan is available.
     */
    function getLastUpdatedTimestamp() external view returns (uint) {
        return lastUpdatedTimestamp;
    }

    /**
     * @notice Forwards the frozen global cost from GlobalContract.
     */
    function frozenGlobalCost() external view returns (int) {
        return globalContract.frozenGlobalCost();
    }

    /**
     * @notice Returns the current iteration weighted-average cluster plan as an array.
     */
    function getClusterOptimalPlanArray() external view returns (int[] memory) {
        int[] memory arr = new int[](numHours);
        for (uint i = 0; i < numHours; i++) {
            arr[i] = clusterOptimalPlan[i];
        }
        return arr;
    }

    /**
     * @notice Returns the addresses of all nodes registered in this cluster.
     */
    function getNodeAddresses() external view returns (address[] memory) {
        return nodeAddresses;
    }

    // ── Internal helpers ──────────────────────────────────────────────────────

    /**
     * @dev Computes per-hour average flexibility weight across all cluster nodes.
     *      Used as the aggregate weight when reporting the cluster result to GlobalContract.
     */
    function _computeAggregateWeights() internal view returns (uint[] memory) {
        uint[] memory avg = new uint[](numHours);
        for (uint i = 0; i < numHours; i++) {
            uint total = 0;
            uint count = 0;
            for (uint j = 0; j < nodeAddresses.length; j++) {
                if (nodeResults[nodeAddresses[j]].exists) {
                    total += nodeResults[nodeAddresses[j]].flexibilityWeight[i];
                    count++;
                }
            }
            avg[i] = (count > 0) ? total / count : 1;
        }
        return avg;
    }
}

contracts/DateTime.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.10;
library DateTime {


    struct _DateTime {
        uint16 year;
        uint8 month;
        uint8 day;
        uint8 hour;
        uint8 minute;
        uint8 second;
        uint8 weekday;
    }

    uint constant DAY_IN_SECONDS = 86400;
    uint constant YEAR_IN_SECONDS = 31536000;
    uint constant LEAP_YEAR_IN_SECONDS = 31622400;

    uint constant HOUR_IN_SECONDS = 3600;
    uint constant MINUTE_IN_SECONDS = 60;

    uint16 constant ORIGIN_YEAR = 1970;

    function isLeapYear(uint16 year) public pure returns (bool) {
        if (year % 4 != 0) {
            return false;
        }
        if (year % 100 != 0) {
            return true;
        }
        if (year % 400 != 0) {
            return false;
        }
        return true;
    }

    function leapYearsBefore(uint year) public pure returns (uint) {
        year -= 1;
        return year / 4 - year / 100 + year / 400;
    }

    function getDaysInMonth(uint8 month, uint16 year) public pure returns (uint8) {
        if (month == 1 || month == 3 || month == 5 || month == 7 || month == 8 || month == 10 || month == 12) {
            return 31;
        }
        else if (month == 4 || month == 6 || month == 9 || month == 11) {
            return 30;
        }
        else if (isLeapYear(year)) {
            return 29;
        }
        else {
            return 28;
        }
    }

    function parseTimestamp(uint timestamp) public pure returns (_DateTime memory dt) {
        uint secondsAccountedFor = 0;
        uint buf;
        uint8 i;

        // Year
        dt.year = getYear(timestamp);
        buf = leapYearsBefore(dt.year) - leapYearsBefore(ORIGIN_YEAR);

        secondsAccountedFor += LEAP_YEAR_IN_SECONDS * buf;
        secondsAccountedFor += YEAR_IN_SECONDS * (dt.year - ORIGIN_YEAR - buf);

        // Month
        uint secondsInMonth;
        for (i = 1; i <= 12; i++) {
            secondsInMonth = DAY_IN_SECONDS * getDaysInMonth(i, dt.year);
            if (secondsInMonth + secondsAccountedFor > timestamp) {
                dt.month = i;
                break;
            }
            secondsAccountedFor += secondsInMonth;
        }

        // Day
        for (i = 1; i <= getDaysInMonth(dt.month, dt.year); i++) {
            if (DAY_IN_SECONDS + secondsAccountedFor > timestamp) {
                dt.day = i;
                break;
            }
            secondsAccountedFor += DAY_IN_SECONDS;
        }

        // Hour
        dt.hour = getHour(timestamp);

        // Minute
        dt.minute = getMinute(timestamp);

        // Second
        dt.second = getSecond(timestamp);

        // Day of week.
        dt.weekday = getWeekday(timestamp);
    }

    function getYear(uint timestamp) public pure returns (uint16) {
        uint secondsAccountedFor = 0;
        uint16 year;
        uint numLeapYears;

        // Year
        year = uint16(ORIGIN_YEAR + timestamp / YEAR_IN_SECONDS);
        numLeapYears = leapYearsBefore(year) - leapYearsBefore(ORIGIN_YEAR);

        secondsAccountedFor += LEAP_YEAR_IN_SECONDS * numLeapYears;
        secondsAccountedFor += YEAR_IN_SECONDS * (year - ORIGIN_YEAR - numLeapYears);

        while (secondsAccountedFor > timestamp) {
            if (isLeapYear(uint16(year - 1))) {
                secondsAccountedFor -= LEAP_YEAR_IN_SECONDS;
            }
            else {
                secondsAccountedFor -= YEAR_IN_SECONDS;
            }
            year -= 1;
        }
        return year;
    }

    function getMonth(uint timestamp) public pure returns (uint8) {
        return parseTimestamp(timestamp).month;
    }

    function getDay(uint timestamp) public pure returns (uint8) {
        return parseTimestamp(timestamp).day;
    }

    function getHour(uint timestamp) public pure returns (uint8) {
        return uint8((timestamp / 60 / 60) % 24);
    }

    function getMinute(uint timestamp) public pure returns (uint8) {
        return uint8((timestamp / 60) % 60);
    }

    function getSecond(uint timestamp) public pure returns (uint8) {
        return uint8(timestamp % 60);
    }

    function getWeekday(uint timestamp) public pure returns (uint8) {
        return uint8((timestamp / DAY_IN_SECONDS + 4) % 7);
    }

}

contracts/DayAheadMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title  DayAheadMarket
 * @notice Implements a 24-hour Day-Ahead (DA) energy market.
 *
 *  Workflow
 *  ────────
 *  1. Off-chain LSTM engine calls openBidding() with renewable + demand forecast.
 *  2. Each prosumer Node calls submitBid() with hourly quantity + price.
 *  3. Operator calls clearMarket() which runs a simplified uniform-price merit
 *     order and stores one Market Clearing Price (MCP) per hour.
 *  4. PSO optimisation in Node contracts uses the DA MCP array as the social
 *     guide so particles converge to the market-optimal schedule.
 *
 *  Fixed-point convention
 *  ──────────────────────
 *  All prices and quantities are stored ×100 (i.e. 5.25 €/kWh → 525).
 *  This avoids Solidity floating-point limitations.
 *
 *  Merit-order clearing
 *  ────────────────────
 *  Renewable generation enters supply at zero marginal cost.
 *  When renewables ≥ demand the MCP collapses toward 0 (or negative),
 *  which is the correct market signal for surplus-RE conditions.
 */
contract DayAheadMarket {

    uint public constant HOURS = 24;

    // ── Operator (market authority / off-chain engine address) ────────────────
    address public operator;

    // ── LSTM forecast committed on-chain for transparency ────────────────────
    int[24] public forecastRenewable; // kWh per hour (×100)
    int[24] public forecastDemand;    // kWh per hour (×100)

    // ── Cleared MCP (result of merit-order clearing) ──────────────────────────
    int[24] public dayAheadMCP;

    // ── Per-node DA schedule assigned after clearing ──────────────────────────
    mapping(address => int[24]) private _nodeSchedule;

    // ── Bid structure ─────────────────────────────────────────────────────────
    struct Bid {
        int[24] quantity; // positive = consume, negative = inject/sell
        int[24] price;    // max WTP (consumers) or min sell price (injectors) ×100
        bool    submitted;
    }
    mapping(address => Bid) public bids;
    address[] public bidders;

    // ── Market day & state ────────────────────────────────────────────────────
    uint public marketDay;     // Unix day index (timestamp / 86400 + 1 for next day)
    bool public biddingOpen;
    bool public marketCleared;

    // ── Events ────────────────────────────────────────────────────────────────
    event BiddingOpened(uint indexed day, uint timestamp);
    event ForecastCommitted(int[24] renewable, int[24] demand, uint timestamp);
    event BidSubmitted(address indexed node, uint timestamp);
    event MarketCleared(int[24] mcp, uint timestamp);

    modifier onlyOperator() {
        require(msg.sender == operator, "DA: only operator");
        _;
    }

    constructor() {
        operator = msg.sender;
    }

    // ── Phase 1: open bidding + commit forecast ───────────────────────────────

    /**
     * @notice Opens bidding for the next day and commits the LSTM forecast.
     *         Called by the off-chain prediction engine after it generates
     *         the 24-hour renewable + demand forecast.
     *
     * @param renewable  24-element array of forecast renewable generation (×100 kWh).
     * @param demand     24-element array of forecast consumption (×100 kWh).
     */
    function openBidding(
        int[24] calldata renewable,
        int[24] calldata demand
    ) external onlyOperator {
        require(!biddingOpen, "DA: bidding already open");

        // Reset previous market state
        marketCleared = false;
        biddingOpen   = true;
        marketDay     = block.timestamp / 86400 + 1; // next calendar day

        // Persist forecast on-chain for auditability
        for (uint i = 0; i < HOURS; i++) {
            forecastRenewable[i] = renewable[i];
            forecastDemand[i]    = demand[i];
        }

        // Clear previous bid registry
        for (uint i = 0; i < bidders.length; i++) {
            delete bids[bidders[i]];
        }
        delete bidders;

        emit BiddingOpened(marketDay, block.timestamp);
        emit ForecastCommitted(renewable, demand, block.timestamp);
    }

    // ── Phase 2: node bid submission ─────────────────────────────────────────

    /**
     * @notice A prosumer node submits its 24-hour bid.
     *
     *   Consumption bid : quantity[h] > 0, price[h] = max willingness-to-pay.
     *   Injection bid   : quantity[h] < 0, price[h] = min acceptable sell price.
     *
     *  The off-chain DA workflow adjusts quantity using weather-scaled
     *  consumption (see data_pipeline.py) before calling this function.
     *
     * @param quantity 24 hourly quantities (×100 kWh).
     * @param price    24 hourly bid prices (×100 €/kWh).
     */
    function submitBid(
        int[24] calldata quantity,
        int[24] calldata price
    ) external {
        require(biddingOpen && !marketCleared, "DA: bidding not active");

        if (!bids[msg.sender].submitted) {
            bidders.push(msg.sender);
        }
        for (uint i = 0; i < HOURS; i++) {
            bids[msg.sender].quantity[i] = quantity[i];
            bids[msg.sender].price[i]    = price[i];
        }
        bids[msg.sender].submitted = true;
        emit BidSubmitted(msg.sender, block.timestamp);
    }

    // ── Phase 3: market clearing ──────────────────────────────────────────────

    /**
     * @notice Clears the DA market hour-by-hour using a merit-order algorithm.
     *
     *  For each hour h:
     *    supply_zero_cost = forecastRenewable[h]     (free renewable)
     *    net_demand       = sum(positive bids) - supply_zero_cost
     *
     *    if net_demand ≤ 0   → MCP = 0 (renewables cover everything, no conventional needed)
     *    else               → MCP = price of the last accepted conventional supply bid
     *                               (the "marginal unit" in the merit order)
     *
     *  All accepted bidders receive the uniform MCP (not their own bid price).
     *  Schedules are set equal to submitted quantities for accepted bids.
     *
     * @dev O(n) scan per hour — suitable for small networks (< 100 nodes).
     */
    function clearMarket() external onlyOperator {
        require(biddingOpen && !marketCleared, "DA: cannot clear");
        require(bidders.length > 0, "DA: no bids");

        for (uint h = 0; h < HOURS; h++) {
            // ── Aggregate demand for this hour ──
            int totalDemand = 0;
            for (uint j = 0; j < bidders.length; j++) {
                if (bids[bidders[j]].quantity[h] > 0) {
                    totalDemand += bids[bidders[j]].quantity[h];
                }
            }

            // ── Net demand after zero-cost renewable supply ──
            int netDemand = totalDemand - forecastRenewable[h];

            int hourMCP;
            if (netDemand <= 0) {
                // Renewable surplus → negative price signal to encourage consumption
                hourMCP = (netDemand * 2) / 100; // mild negative price per unit surplus
            } else {
                // Find the cheapest injection bids to satisfy remaining demand.
                // Walk through bids in ascending price order (greedy merit order).
                int remaining = netDemand;
                int marginal  = 0;
                bool satisfied = false;

                // Simple O(n) minimum-price scan (sufficient for < 100 nodes)
                bool[] memory used = new bool[](bidders.length);
                while (remaining > 0) {
                    int   bestPrice   = type(int).max;
                    uint  bestIdx     = type(uint).max;
                    for (uint j = 0; j < bidders.length; j++) {
                        if (
                            !used[j] &&
                            bids[bidders[j]].quantity[h] < 0 &&
                            bids[bidders[j]].price[h] < bestPrice
                        ) {
                            bestPrice = bids[bidders[j]].price[h];
                            bestIdx   = j;
                        }
                    }
                    if (bestIdx == type(uint).max) break; // no more supply bids
                    used[bestIdx] = true;
                    marginal       = bestPrice;
                    remaining     += bids[bidders[bestIdx]].quantity[h]; // negative qty
                    if (remaining <= 0) { satisfied = true; break; }
                }
                hourMCP = satisfied ? marginal : forecastDemand[h] / 10; // fallback: 10% of demand as price
            }

            dayAheadMCP[h] = hourMCP;

            // Assign schedules (accepted quantity = submitted quantity)
            for (uint j = 0; j < bidders.length; j++) {
                _nodeSchedule[bidders[j]][h] = bids[bidders[j]].quantity[h];
            }
        }

        biddingOpen   = false;
        marketCleared = true;
        emit MarketCleared(dayAheadMCP, block.timestamp);
    }

    // ── Getters ───────────────────────────────────────────────────────────────

    function getDayAheadMCP() external view returns (int[24] memory) {
        return dayAheadMCP;
    }

    function getNodeSchedule(address node) external view returns (int[24] memory) {
        return _nodeSchedule[node];
    }

    function getForecastRenewable() external view returns (int[24] memory) {
        return forecastRenewable;
    }

    function getForecastDemand() external view returns (int[24] memory) {
        return forecastDemand;
    }

    function getBidderCount() external view returns (uint) {
        return bidders.length;
    }

    function getMCPForHour(uint hour) external view returns (int) {
        require(hour < HOURS, "DA: invalid hour");
        return dayAheadMCP[hour];
    }
}

contracts/GlobalContract.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;
/* CONTRACTUL GLOBAL
   Acest contract colectează rezultatele de la toate nodurile, stocate într-un mapping,
   și calculează planul optim global folosind un mapping (cheia fiind ora din zi).
   Astfel se elimină necesitatea de a gestiona explicit matrice 2D.
*/

/* INTERFAȚĂ PENTRU GLOBAL CONTRACT */
interface GlobalContractInterface {
    function updateNodeResult(
        int[] calldata newPosition,
        int newScore,
        uint[] calldata newFlexibilityWeight
    ) external;
    function getGlobalOptimalPlanArray() external view returns (int[] memory);
    function getLastUpdatedTimestamp() external view returns (uint);
    function getBestGlobalPlan() external view returns (int[] memory);
    function frozenGlobalCost() external view returns (int);
}

contract GlobalContract {
    struct NodeResult {
        int[] bestPosition;
        int bestScore;
        uint[] flexibilityWeight;
        bool exists;
    }

    // Mapping de la adresa nodului la rezultatul său
    mapping(address => NodeResult) public nodeResults;
    // Lista adreselor nodurilor înregistrate
    address[] public nodeAddresses;

    // ── Cluster registry ────────────────────────────────────────────────────
    // Tracks which nodeAddresses entries are ClusterContracts rather than
    // individual nodes.  Purely informational — the aggregation logic is identical
    // because a ClusterContract reports itself as a single "super-node".
    mapping(address => bool) public isCluster;
    // Mapping de la oră (index) la valoarea optimă agregată (planul global)
    mapping(uint => int) public globalOptimalPlan;
    // Numărul de ore pentru care se definește planul (ex.: 24)
    uint public numHours;

    // Variabile noi pentru stocarea celui mai bun rezultat global
    int public bestGlobalCost = type(int).max;
    int[] public bestGlobalPlan;

    int public frozenGlobalCost;
    uint public lastUpdatedTimestamp; // Momentul ultimei actualizări globale

    bool public finalized = false;

    event NodeResultUpdated(address indexed node, int bestScore);
    event GlobalPlanComputed(
        address indexed trigger,
        int[] newPlan,
        uint timestamp
    );
    /// @notice Emitted when a ClusterContract registers itself as a cluster aggregator.
    event ClusterRegistered(address indexed cluster);

    // Nodurile apelează această funcție pentru a-și transmite rezultatul optim.
    // Se folosește un mapping pentru a stoca rezultatele și o listă pentru a itera ulterior.
    function updateNodeResult(
        int[] calldata newPosition,
        int newScore,
        uint[] calldata newFlexibilityWeight
    ) external {
        if (!nodeResults[msg.sender].exists) {
            nodeResults[msg.sender] = NodeResult(
                newPosition,
                newScore,
                newFlexibilityWeight,
                true
            );
            nodeAddresses.push(msg.sender);
        } else {
            if (newScore < nodeResults[msg.sender].bestScore) {
                nodeResults[msg.sender].bestScore = newScore;
                nodeResults[msg.sender].bestPosition = newPosition;
                nodeResults[msg.sender]
                    .flexibilityWeight = newFlexibilityWeight;
            }
        }
        // Setează numărul de ore din planul de consum, dacă nu a fost deja stabilit.
        if (numHours == 0) {
            numHours = newPosition.length;
        } else {
            require(
                newPosition.length == numHours,
                "Dimensiune necorespunzatoare"
            );
        }
        emit NodeResultUpdated(msg.sender, newScore);
    }

    /**
     * @notice Called by a ClusterContract to declare itself as a cluster aggregator.
     *         This is optional and purely informational — it marks the caller's address
     *         in the isCluster mapping so off-chain tooling can distinguish clusters from
     *         individual nodes when reading nodeAddresses.
     *
     *         ClusterContracts should call this once after deployment.
     */
    function registerAsCluster() external {
        isCluster[msg.sender] = true;
        emit ClusterRegistered(msg.sender);
    }

    // Returnează planul global complet sub formă de array.
    function getGlobalOptimalPlanArray() external view returns (int[] memory) {
        int[] memory copy = new int[](numHours);
        for (uint i = 0; i < numHours; i++) {
            copy[i] = globalOptimalPlan[i];
        }
        return copy;
    }

    // Calculează planul global optim. Pentru fiecare oră, se calculează media planurilor
    // optime ale nodurilor și se stochează în mapping-ul globalOptimalPlan.
    function computeGlobalOptimalPlan() public {
        require(nodeAddresses.length > 0, "Niciun nod inregistrat");
        require(numHours > 0, "numHours nu este setat");

        // Calculul planului global curent ca medie ponderată
        for (uint i = 0; i < numHours; i++) {
            int weightedSum = 0;
            uint totalWeight = 0;
            for (uint j = 0; j < nodeAddresses.length; j++) {
                if (nodeResults[nodeAddresses[j]].exists) {
                    uint weight = nodeResults[nodeAddresses[j]]
                        .flexibilityWeight[i];
                    weightedSum +=
                        int(weight) *
                        nodeResults[nodeAddresses[j]].bestPosition[i];
                    totalWeight += weight;
                }
            }
            if (totalWeight > 0) {
                globalOptimalPlan[i] = weightedSum / int(totalWeight);
            } else {
                globalOptimalPlan[i] = 5; // Valoare default
            }
        }
        lastUpdatedTimestamp = block.timestamp;
        emit GlobalPlanComputed(
            msg.sender,
            this.getGlobalOptimalPlanArray(),
            lastUpdatedTimestamp
        );

        // Calculează costul total curent al rețelei (suma costurilor minime ale nodurilor)
        int currentNetworkCost = 0;
        for (uint j = 0; j < nodeAddresses.length; j++) {
            if (nodeResults[nodeAddresses[j]].exists) {
                currentNetworkCost += nodeResults[nodeAddresses[j]].bestScore;
            }
        }

        // Actualizează bestGlobalPlan doar dacă s-a găsit un cost mai mic
        if (bestGlobalPlan.length == 0 || currentNetworkCost < bestGlobalCost) {
            bestGlobalCost = currentNetworkCost;
            if (bestGlobalPlan.length != numHours) {
                bestGlobalPlan = new int[](numHours);
            }
            for (uint i = 0; i < numHours; i++) {
                bestGlobalPlan[i] = globalOptimalPlan[i];
            }
        }
    }

    // Funcția pentru a "îngheța" soluția finală
    function finalizePlan() external {
        finalized = true;
        frozenGlobalCost = bestGlobalCost;
    }
    // Returnează valoarea planului global pentru o anumită oră.
    function getGlobalOptimalPlanHour(uint hour) external view returns (int) {
        require(hour < numHours, "Ora in afara intervalului");
        return globalOptimalPlan[hour];
    }

    function getBestGlobalPlan() external view returns (int[] memory) {
        return bestGlobalPlan;
    }

    function getBestPosition(address _node) public view returns (int[] memory) {
        return nodeResults[_node].bestPosition;
    }

    function getLastUpdatedTimestamp() external view returns (uint) {
        return lastUpdatedTimestamp;
    }

    function getNodeAddresses() public view returns (address[] memory) {
        return nodeAddresses;
    }
}

contracts/IntradayMarket.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/**
 * @title  IntradayMarket
 * @notice Implements a real-time Intra-Day (ID) energy market with 96
 *         fifteen-minute intervals per day (24 h × 4).
 *
 *  Workflow (every 15 minutes, triggered off-chain)
 *  ─────────────────────────────────────────────────
 *  1. The PSO engine runs a fast intraday optimisation using the latest
 *     weather data and the deviations accumulated since the DA schedule.
 *  2. It calls updateInterval() with:
 *       - the new MCP for this 15-min slot
 *       - the PSO-computed aggregate adjustment
 *       - per-node deviations from the DA schedule
 *  3. Nodes that deviate from their DA schedule incur an imbalance cost
 *     (penaltyPositive for over-consumption, penaltyNegative rebate for under-consumption).
 *  4. The off-chain LSTM re-forecasts renewable generation hourly and commits
 *     the updated 15-min forecast via updateRenewableForecast().
 *
 *  Relationship with DA market
 *  ────────────────────────────
 *  The DA schedule (from DayAheadMarket.sol) is the reference baseline.
 *  ID trading allows prosumers to trade the delta between DA schedule and
 *  actual production/consumption at the real-time MCP.
 *
 *  Fixed-point: all values ×100.
 */
contract IntradayMarket {

    uint public constant INTERVALS_PER_DAY = 96; // 24 × 4  (15-min resolution)

    // ── MCP array for all 96 intervals ────────────────────────────────────────
    // Updated progressively as each interval closes.
    int[96] public intradayMCP;

    // ── PSO-computed aggregate adjustment per interval ────────────────────────
    // Represents the total network consumption adjustment the PSO recommended.
    mapping(uint => int) public psoAdjustedAggregate;

    // ── Per-node deviation tracking ───────────────────────────────────────────
    // deviation[node][interval] = actual_consumption - da_schedule (×100 kWh)
    // Positive  → node consumed MORE than its DA schedule (over-delivery risk)
    // Negative  → node consumed LESS  (under-delivery)
    mapping(address => mapping(uint => int)) public deviation;

    // ── Imbalance penalty / rebate coefficients (×100 €/kWh) ─────────────────
    int public penaltyPositive = 300; // 3.00 €/kWh for over-consumption
    int public penaltyNegative = 150; // 1.50 €/kWh rebate for under-consumption

    // ── Rolling weather-adjusted renewable forecast ───────────────────────────
    // Updated each time new weather data arrives (typically once per hour).
    int[96] public forecastRenewable15min;

    // ── Market state ──────────────────────────────────────────────────────────
    uint public currentInterval;  // last updated interval index (0-95)
    uint public lastUpdateBlock;
    uint public marketDay;        // Unix day index
    address public operator;

    // ── Reference to the DA market for reading the base schedule ─────────────
    address public dayAheadMarketAddress;

    // ── Events ────────────────────────────────────────────────────────────────
    event IntervalUpdated(
        uint indexed interval,
        int  mcp,
        int  psoAggregate,
        uint timestamp
    );
    event DeviationRecorded(address indexed node, uint indexed interval, int dev);
    event RenewableForecastUpdated(uint timestamp);
    event PenaltiesUpdated(int positive, int negative);

    modifier onlyOperator() {
        require(msg.sender == operator, "ID: only operator");
        _;
    }

    constructor(address _dayAheadMarket) {
        operator             = msg.sender;
        dayAheadMarketAddress = _dayAheadMarket;
        marketDay            = block.timestamp / 86400;
    }

    // ── Core interval update (called by PSO engine every 15 min) ─────────────

    /**
     * @notice Updates a 15-minute interval with new MCP and PSO results.
     *
     *  Called by the off-chain intraday PSO engine after it:
     *    1. Reads real-time smart-meter data (actual consumption).
     *    2. Computes deviations from each node's DA schedule.
     *    3. Runs one PSO iteration to minimise imbalance cost.
     *    4. Derives a new equilibrium MCP for this slot.
     *
     * @param intervalIndex  0–95 slot index.
     * @param newMCP         Cleared MCP for this slot (×100 €/kWh).
     * @param aggregateAdj   Total network consumption adjustment (×100 kWh).
     * @param nodeAddresses  Prosumer node addresses.
     * @param nodeDeviations Corresponding deviations from DA schedule (×100 kWh).
     */
    function updateInterval(
        uint      intervalIndex,
        int       newMCP,
        int       aggregateAdj,
        address[] calldata nodeAddresses,
        int[]     calldata nodeDeviations
    ) external onlyOperator {
        require(intervalIndex < INTERVALS_PER_DAY, "ID: invalid interval");
        require(nodeAddresses.length == nodeDeviations.length, "ID: array mismatch");

        intradayMCP[intervalIndex]          = newMCP;
        psoAdjustedAggregate[intervalIndex] = aggregateAdj;
        currentInterval                     = intervalIndex;
        lastUpdateBlock                     = block.number;

        // Record per-node deviations for settlement at end of day
        for (uint i = 0; i < nodeAddresses.length; i++) {
            deviation[nodeAddresses[i]][intervalIndex] = nodeDeviations[i];
            emit DeviationRecorded(nodeAddresses[i], intervalIndex, nodeDeviations[i]);
        }

        emit IntervalUpdated(intervalIndex, newMCP, aggregateAdj, block.timestamp);
    }

    // ── Renewable forecast update (called when new weather data arrives) ──────

    /**
     * @notice Updates the 15-minute renewable generation forecast.
     *         The off-chain LSTM re-runs whenever fresh weather data arrives
     *         (typically hourly from the weather API) and commits the new
     *         96-slot forecast here.
     *
     * @param forecast 96-element array of forecast renewable generation (×100 kWh).
     */
    function updateRenewableForecast(
        int[96] calldata forecast
    ) external onlyOperator {
        for (uint i = 0; i < INTERVALS_PER_DAY; i++) {
            forecastRenewable15min[i] = forecast[i];
        }
        emit RenewableForecastUpdated(block.timestamp);
    }

    // ── Imbalance settlement ──────────────────────────────────────────────────

    /**
     * @notice Computes the total imbalance cost for a node over a range of intervals.
     *
     *  Over-consumption (deviation > 0): cost = deviation × penaltyPositive
     *  Under-consumption (deviation < 0): cost = deviation × penaltyNegative
     *    → negative × negative = positive (rebate reduces total cost)
     *
     * @param node      Node address.
     * @param fromSlot  Inclusive start interval.
     * @param toSlot    Inclusive end interval.
     * @return cost     Net imbalance cost (×100 ×100 — divide by 10000 for €).
     */
    function computeImbalanceCost(
        address node,
        uint    fromSlot,
        uint    toSlot
    ) external view returns (int cost) {
        for (uint i = fromSlot; i <= toSlot && i < INTERVALS_PER_DAY; i++) {
            int dev = deviation[node][i];
            if (dev > 0) {
                cost += dev * penaltyPositive;      // penalty for over-consumption
            } else if (dev < 0) {
                cost += dev * penaltyNegative;      // rebate (negative cost) for under-consumption
            }
        }
    }

    /**
     * @notice Operator adjusts imbalance penalty rates to reflect regulatory changes.
     *         In a real market, these coefficients are set by the grid operator (TSO).
     */
    function setPenalties(int positive, int negative) external onlyOperator {
        require(positive >= 0 && negative >= 0, "ID: non-negative penalties");
        penaltyPositive = positive;
        penaltyNegative = negative;
        emit PenaltiesUpdated(positive, negative);
    }

    // ── Getters ───────────────────────────────────────────────────────────────

    function getIntradayMCPFull() external view returns (int[96] memory) {
        return intradayMCP;
    }

    function getMCPForInterval(uint interval) external view returns (int) {
        require(interval < INTERVALS_PER_DAY, "ID: invalid interval");
        return intradayMCP[interval];
    }

    function getDeviation(address node, uint interval) external view returns (int) {
        return deviation[node][interval];
    }

    function getRenewableForecast15min() external view returns (int[96] memory) {
        return forecastRenewable15min;
    }

    function getCurrentIntervalIndex() external view returns (uint) {
        // Derives the current expected interval from block timestamp
        uint secondsInDay = block.timestamp % 86400;
        return secondsInDay / 900; // 900 seconds = 15 minutes
    }
}

contracts/Node.sol.content:
//SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/* INTERFAȚĂ PENTRU GLOBAL CONTRACT */
interface GlobalContractInterface {
    function updateNodeResult(
        int[] calldata newPosition,
        int newScore,
        uint[] calldata newFlexibilityWeight
    ) external;
    function getGlobalOptimalPlanArray() external view returns (int[] memory);
    function getLastUpdatedTimestamp() external view returns (uint);
    function getBestGlobalPlan() external view returns (int[] memory);
    function frozenGlobalCost() external view returns (int);
}

/**
 * @notice Interface for ClusterContract — the PSO neighbourhood aggregator.
 *         Exposes the same updateNodeResult / getLastUpdatedTimestamp signatures as
 *         GlobalContractInterface so Node contracts can be wired to a cluster with
 *         no constructor changes.  The additional getClusterBestPlan() method returns
 *         the intra-cluster best plan used as the PSO social (neighbourhood) guide.
 */
interface IClusterContract {
    function updateNodeResult(
        int[] calldata newPosition,
        int newScore,
        uint[] calldata newFlexibilityWeight
    ) external;
    /// @notice Intra-cluster best plan — used as the c2 social guide in velocity update.
    function getClusterBestPlan() external view returns (int[] memory);
    /// @notice Forwards the network-wide best plan for global-deviation penalty calculation.
    function getBestGlobalPlan() external view returns (int[] memory);
    function getLastUpdatedTimestamp() external view returns (uint);
    function frozenGlobalCost() external view returns (int);
}

/* CONTRACTUL PENTRU UN NOD (prosumer)
   Fiecare nod își gestionează planul de consum pe ore și își actualizează
   poziția și costul folosind un algoritm PSO. Se salvează snapshot-ul costului
   optim și al anumitor parametri (ex.: resurse regenerabile și nivelul bateriei)
   pentru a putea recalcula costul ulterior, în condiții identice.
*/
contract Node {
    // Vectorii pentru planul de consum (ex: 24 de ore)
    int[] public position;
    int[] public velocity;
    int[] public personalBestPosition;
    int public personalBestScore = type(int).max;
    uint public lastKnownGlobalTimestamp;

    // Parametrii PSO (scalari — folosiți ca fallback când TDM nu este activat)
    int public w = 50;
    int public c1 = 200;
    int public c2 = 200;

    // ── TDM PSO parameters ────────────────────────────────────────────────────
    // Per-hour arrays that override the scalar values above once tdmEnabled = true.
    // Typical strategy:
    //   • Peak hours   (07-09, 17-20): low w (less inertia), high c2 (align with cluster)
    //   • Off-peak     (22-06):        high w (keep momentum), high c1 (explore personally)
    //   • Shoulder     (rest):         medium values
    int[] public w_tdm;
    int[] public c1_tdm;
    int[] public c2_tdm;
    bool  public tdmEnabled;

    // Date specifice nodului
    int[] public tariff;
    uint[] public capacity;
    uint[] public renewableGeneration;
    uint[] public batteryCapacity;
    uint[] public batteryCharge;
    uint[] public flexibleLoad;
    int[] public baselinePosition;

    // Penalizări locale (scalare — fallback când TDM nu este activat)
    int public ALPHA = 75;
    int public BETA = 43;
    int public GAMMA = 18;

    // ── TDM penalty parameters ────────────────────────────────────────────────
    // Per-hour penalty coefficients.  Example:
    //   • Peak hours:   higher ALPHA (capacity constraints tighter)
    //   • Off-peak:     lower BETA/GAMMA (more flexibility tolerance)
    int[] public ALPHA_tdm;
    int[] public BETA_tdm;
    int[] public GAMMA_tdm;

    // Parametrii pentru influența planului global
    int constant PENALTY_GLOBAL = 4;
    int constant REDEEM_GLOBAL = 2;

    // Valorile de flexibilitate
    uint[] public flexibilityAbove;
    uint[] public flexibilityBelow;

    GlobalContractInterface public globalContract;

    /// @notice Optional cluster reference.  When set:
    ///   • node reports its result to the cluster instead of directly to GlobalContract;
    ///   • velocity update uses cluster best plan as PSO social guide (hierarchical PSO).
    /// When address(0), the node operates in classic flat-PSO mode (backwards compatible).
    IClusterContract public clusterContract;

    event BestPositionUpdated(address indexed node, int newScore);
    event NewPlanReceived(uint timestamp);
    event ClusterContractSet(address indexed cluster);
    event TDMParametersSet(uint numSlots);

    // changed: Adăugăm variabile pentru snapshot-ul parametrilor critici
    uint[] public frozenRenewableGeneration;
    uint[] public frozenBatteryCharge;

    // Constructor extins
    constructor(
        address globalContractAddress,
        int[] memory initialPosition,
        int[] memory initialVelocity,
        int[] memory initialTariff,
        uint[] memory initialCapacity,
        uint[] memory initialRenewableGeneration,
        uint[] memory initialBatteryCapacity,
        uint[] memory initialBatteryCharge,
        uint[] memory initialFlexibleLoad,
        uint[] memory _flexibilityAbove,
        uint[] memory _flexibilityBelow
    ) {
        globalContract = GlobalContractInterface(globalContractAddress);
        baselinePosition = initialPosition;
        position = new int[](initialPosition.length);
        velocity = new int[](initialVelocity.length);
        personalBestPosition = new int[](initialPosition.length);
        tariff = new int[](initialTariff.length);
        capacity = new uint[](initialCapacity.length);
        renewableGeneration = new uint[](initialRenewableGeneration.length);
        batteryCapacity = new uint[](initialBatteryCapacity.length);
        batteryCharge = new uint[](initialBatteryCharge.length);
        flexibleLoad = new uint[](initialFlexibleLoad.length);
        flexibilityAbove = new uint[](_flexibilityAbove.length);
        flexibilityBelow = new uint[](_flexibilityBelow.length);

        for (uint i = 0; i < initialPosition.length; i++) {
            position[i] = initialPosition[i];
            personalBestPosition[i] = initialPosition[i];
            velocity[i] = initialVelocity[i];
            tariff[i] = initialTariff[i];
            capacity[i] = initialCapacity[i];
            renewableGeneration[i] = initialRenewableGeneration[i];
            batteryCapacity[i] = initialBatteryCapacity[i];
            batteryCharge[i] = initialBatteryCharge[i];
            flexibleLoad[i] = initialFlexibleLoad[i];
            flexibilityAbove[i] = _flexibilityAbove[i];
            flexibilityBelow[i] = _flexibilityBelow[i];
        }
    }

    // ── TDM & Cluster Configuration ──────────────────────────────────────────

    /**
     * @notice Assign a ClusterContract as this node's neighbourhood aggregator.
     *         Once set, the node reports results to the cluster and uses the
     *         cluster best plan as its PSO social guide (c2 term).
     * @param _cluster Address of the deployed ClusterContract.
     *                 Pass address(0) to detach and revert to flat-PSO mode.
     */
    function setClusterContract(address _cluster) external {
        clusterContract = IClusterContract(_cluster);
        emit ClusterContractSet(_cluster);
    }

    /**
     * @notice Activate Time-Division Multiplexing for PSO and penalty parameters.
     *         Each array must have exactly position.length elements (one per hour).
     *
     *         Suggested 24-hour profile (scale values × 100 for fixed-point):
     *           w      — 70 off-peak, 40 peak  (higher inertia in quiet hours)
     *           c1     — 250 off-peak, 150 peak (more personal exploration off-peak)
     *           c2     — 150 off-peak, 250 peak (stronger social alignment at peak)
     *           ALPHA  — 50 off-peak, 100 peak  (strict capacity at peak)
     *           BETA   — 30 off-peak, 60 peak
     *           GAMMA  — 10 off-peak, 25 peak
     */
    function setTDMParameters(
        int[] calldata _w,
        int[] calldata _c1,
        int[] calldata _c2,
        int[] calldata _alpha,
        int[] calldata _beta,
        int[] calldata _gamma
    ) external {
        uint n = position.length;
        require(
            _w.length == n && _c1.length == n && _c2.length == n &&
            _alpha.length == n && _beta.length == n && _gamma.length == n,
            "TDM array length mismatch"
        );
        w_tdm     = _w;
        c1_tdm    = _c1;
        c2_tdm    = _c2;
        ALPHA_tdm = _alpha;
        BETA_tdm  = _beta;
        GAMMA_tdm = _gamma;
        tdmEnabled = true;
        emit TDMParametersSet(n);
    }

    // ── TDM-aware internal getters ────────────────────────────────────────────

    /// @dev Returns the inertia weight for a given hour slot (TDM-aware).
    function _getW(uint hour) internal view returns (int) {
        return (tdmEnabled && w_tdm.length > hour) ? w_tdm[hour] : w;
    }

    /// @dev Returns the cognitive (personal-best) coefficient for a given hour (TDM-aware).
    function _getC1(uint hour) internal view returns (int) {
        return (tdmEnabled && c1_tdm.length > hour) ? c1_tdm[hour] : c1;
    }

    /// @dev Returns the social (neighbourhood-best) coefficient for a given hour (TDM-aware).
    function _getC2(uint hour) internal view returns (int) {
        return (tdmEnabled && c2_tdm.length > hour) ? c2_tdm[hour] : c2;
    }

    /// @dev Returns the over-consumption penalty for a given hour (TDM-aware).
    function _getALPHA(uint hour) internal view returns (int) {
        return (tdmEnabled && ALPHA_tdm.length > hour) ? ALPHA_tdm[hour] : ALPHA;
    }

    /// @dev Returns the flexibility-violation penalty for a given hour (TDM-aware).
    function _getBETA(uint hour) internal view returns (int) {
        return (tdmEnabled && BETA_tdm.length > hour) ? BETA_tdm[hour] : BETA;
    }

    /// @dev Returns the unused-renewable penalty for a given hour (TDM-aware).
    function _getGAMMA(uint hour) internal view returns (int) {
        return (tdmEnabled && GAMMA_tdm.length > hour) ? GAMMA_tdm[hour] : GAMMA;
    }

    /* 
       Funcția obiectiv calculează costul total de energie pentru un plan de consum,
       ținând cont de consum, tarife, penalizări locale și ajustări globale.
    */
    function objectiveFunction(int[] memory pos) public view returns (int) {
        int totalCost = 0;
        uint len = pos.length;
        // Copii locale ale valorilor curente
        uint[] memory tempRenewable = renewableGeneration;
        uint[] memory tempBattery = batteryCharge;

        int[] memory globalPlan = globalContract.getBestGlobalPlan();

        for (uint i = 0; i < len; i++) {
            int consumption = pos[i];
            int localCost = 0;

            if (consumption < 0) {
                // int effectiveTariff = getEffectiveTariff(i, consumption);
                // localCost = -effectiveTariff * (-consumption);
                int exportTariff = int(tariff[i]); // sau poți seta o constantă fixă, ex: 5
                localCost = exportTariff * consumption; // va fi un număr pozitiv (cost)
            } else {
                uint cons = uint(consumption);
                if (tempRenewable[i] >= cons) {
                    tempRenewable[i] -= cons;
                    cons = 0;
                } else {
                    cons -= tempRenewable[i];
                    tempRenewable[i] = 0;
                }
                if (tempBattery[i] >= cons) {
                    tempBattery[i] -= cons;
                    cons = 0;
                } else {
                    cons -= tempBattery[i];
                    tempBattery[i] = 0;
                }
                localCost = int(tariff[i]) * int(cons);
            }

            int overConsumption = consumption > int(capacity[i])
                ? consumption - int(capacity[i])
                : int(0);
            int bestCons = personalBestPosition[i];
            int flex = int(flexibilityAbove[i] + flexibilityBelow[i]);
            int diff = consumption - bestCons;
            int absDiff = diff >= 0 ? diff : -diff;
            int flexibilityViolation = absDiff > flex ? absDiff - flex : int(0);
            int maxRenew = int(renewableGeneration[i]);
            int unusedRenewable = maxRenew > consumption
                ? maxRenew - consumption
                : int(0);
            // TDM-aware penalties: different weights for each hour slot.
            int localPenalty = overConsumption    * _getALPHA(i) +
                               flexibilityViolation * _getBETA(i)  +
                               unusedRenewable    * _getGAMMA(i);

            int globalAdjustment = 0;
            if (globalPlan.length == len) {
                int globalValue = globalPlan[i];
                int deviation = consumption - globalValue;
                int absDeviation = deviation >= 0 ? deviation : -deviation;
                int threshold = globalValue != 0 ? globalValue / 10 : int(0);
                if (absDeviation > threshold) {
                    if (deviation > 0) {
                        globalAdjustment =
                            (absDeviation - threshold) *
                            PENALTY_GLOBAL;
                    } else {
                        globalAdjustment = -((absDeviation - threshold) *
                            REDEEM_GLOBAL);
                    }
                }
            }
            int hourCost = localCost + localPenalty + globalAdjustment;
            totalCost += hourCost;
        }
        return totalCost;
    }

    // Funcția de calcul a tarifului efectiv (cu discount)  Ar fi o idee sa le fac variabile in functie de ore
    function getEffectiveTariff(
        uint hour,
        int consumption
    ) public view returns (int) {
        // int base = int(tariff[hour]);
        // if (consumption < 0) {
        //     uint absConsumption = uint(-consumption);
        //     uint extraDiscount = absConsumption / 2;
        //     uint totalDiscount = 20 + extraDiscount;
        //     if (totalDiscount > 40) {
        //         totalDiscount = 40;
        //     }
        //     return (base * int(100 - totalDiscount)) / 100;
        // } else {
        //     return base;
        // }
        return int(tariff[hour]);
    }

    // Actualizează cea mai bună poziție și transmite rezultatul către GlobalContract.
    function updateBestPositions() public {
        int currentScore = objectiveFunction(position);
        if (currentScore < personalBestScore) {
            personalBestScore = currentScore;
            personalBestPosition = position;
            // : Salvăm și snapshot-ul valorilor critice la momentul obținerii celui mai bun cost.
            delete frozenRenewableGeneration;
            delete frozenBatteryCharge;
            for (uint i = 0; i < renewableGeneration.length; i++) {
                frozenRenewableGeneration.push(renewableGeneration[i]);
                frozenBatteryCharge.push(batteryCharge[i]);
            }
            emit BestPositionUpdated(address(this), currentScore);
        }
        uint[] memory flexWeights = calculateFlexibilityWeight();
        // Report to cluster if one is assigned; otherwise report directly to GlobalContract.
        if (address(clusterContract) != address(0)) {
            clusterContract.updateNodeResult(position, currentScore, flexWeights);
        } else {
            globalContract.updateNodeResult(position, currentScore, flexWeights);
        }
    }

    // Calculează "ponderile de flexibilitate" pentru fiecare oră.
    function calculateFlexibilityWeight()
        internal
        view
        returns (uint[] memory)
    {
        uint len = flexibilityAbove.length;
        uint[] memory weights = new uint[](len);
        for (uint i = 0; i < len; i++) {
            weights[i] = (flexibilityAbove[i] + flexibilityBelow[i]) / 2;
        }
        return weights;
    }

    mapping(uint256 => int256) public usedRenewablePerHour;

    function updateVelocityAndPosition() public {
        uint globalTimestamp = globalContract.getLastUpdatedTimestamp();
        if (globalTimestamp > lastKnownGlobalTimestamp) {
            lastKnownGlobalTimestamp = globalTimestamp;
            emit NewPlanReceived(globalTimestamp);
        }

        // Social (neighbourhood) guide:
        //   • With cluster: use cluster best plan  → hierarchical PSO neighbourhood-best
        //   • Without cluster: fall back to global best plan  → classic flat PSO
        int[] memory socialPlan = (address(clusterContract) != address(0))
            ? clusterContract.getClusterBestPlan()
            : globalContract.getBestGlobalPlan();
        require(socialPlan.length == position.length, "Dimensiuni inegale");

        for (uint i = 0; i < position.length; i++) {
            uint r1 = uint(
                keccak256(abi.encodePacked(block.timestamp, i, position[i]))
            ) % 100;
            uint r2 = uint(
                keccak256(abi.encodePacked(block.timestamp, i + 1, velocity[i]))
            ) % 100;
            int randomFactor = int(
                uint(
                    keccak256(abi.encodePacked(block.timestamp, i, velocity[i]))
                ) % 101
            ) - 50;

            int diffPersonal = personalBestPosition[i] - position[i];
            // diffSocial uses the neighbourhood-best (cluster or global) for the c2 term.
            int diffSocial = socialPlan[i] - position[i];

            // TDM-aware PSO coefficients: inertia, cognitive, and social weights are
            // specific to the current hour slot, allowing peak-vs-off-peak tuning.
            velocity[i] =
                (_getW(i) *
                    velocity[i] +
                    (_getC1(i) * int(r1) * diffPersonal) /
                    100 +
                    (_getC2(i) * int(r2) * diffSocial) /
                    100 +
                    randomFactor) /
                100;

            position[i] += velocity[i];

            int minTotal = int(flexibilityBelow[i]);
            int maxTotal = int(flexibilityAbove[i]);
            int renewable = int(renewableGeneration[i]);
            usedRenewablePerHour[i] = 0;

            int usedRenewable = renewable;
            if (position[i] + usedRenewable > maxTotal) {
                usedRenewable = maxTotal - position[i]; 
            }
            if (usedRenewable < 0) {
                usedRenewable = 0;
            }

            usedRenewablePerHour[i] = usedRenewable;

            // Actualizează consumul total
            int total = position[i] + usedRenewable;

            // Dacă totalul este sub minimul permis → completezi din grid (crești position)
            if (total < minTotal) {
                int neededFromGrid = minTotal - total;
                position[i] += neededFromGrid;
                total = minTotal;
            }

            // Dacă totalul depășește maximul permis → ajustezi regenerabilul în jos
            if (total > maxTotal) {
                int overflow = total - maxTotal;
                if (usedRenewablePerHour[i] >= overflow) {
                    usedRenewablePerHour[i] -= overflow;
                } else {
                    int rest = overflow - usedRenewablePerHour[i];
                    usedRenewablePerHour[i] = 0;
                    position[i] -= rest;
                }
            }
        }
    }

    function objectiveFunctionFrozen(
        int[] memory pos
    ) public view returns (int) {
        int totalCost = 0;
        uint len = pos.length;
        // Copiem snapshot-ul valorilor salvate
        uint[] memory tempRenewable = new uint[](
            frozenRenewableGeneration.length
        );
        for (uint i = 0; i < frozenRenewableGeneration.length; i++) {
            tempRenewable[i] = frozenRenewableGeneration[i];
        }
        uint[] memory tempBattery = new uint[](frozenBatteryCharge.length);
        for (uint i = 0; i < frozenBatteryCharge.length; i++) {
            tempBattery[i] = frozenBatteryCharge[i];
        }
        int[] memory globalPlan = globalContract.getBestGlobalPlan();

        for (uint i = 0; i < len; i++) {
            int consumption = pos[i];
            int localCost = 0;

            if (consumption < 0) {
                // int effectiveTariff = getEffectiveTariff(i, consumption);
                // localCost = -effectiveTariff * (-consumption);
                int exportTariff = int(tariff[i]); // sau poți seta o constantă fixă, ex: 5
                localCost = exportTariff * consumption; // va fi un număr pozitiv (cost)
            } else {
                uint cons = uint(consumption);
                if (tempRenewable[i] >= cons) {
                    tempRenewable[i] -= cons;
                    cons = 0;
                } else {
                    cons -= tempRenewable[i];
                    tempRenewable[i] = 0;
                }
                if (tempBattery[i] >= cons) {
                    tempBattery[i] -= cons;
                    cons = 0;
                } else {
                    cons -= tempBattery[i];
                    tempBattery[i] = 0;
                }
                localCost = int(tariff[i]) * int(cons);
            }

            int overConsumption = consumption > int(capacity[i])
                ? consumption - int(capacity[i])
                : int(0);
            int bestCons = personalBestPosition[i];
            int flex = int(flexibilityAbove[i] + flexibilityBelow[i]);
            int diff = consumption - bestCons;
            int absDiff = diff >= 0 ? diff : -diff;
            int flexibilityViolation = absDiff > flex ? absDiff - flex : int(0);
            // Folosim snapshot-ul pentru resurse regenerabile
            int maxRenew = int(frozenRenewableGeneration[i]);
            int unusedRenewable = maxRenew > consumption
                ? maxRenew - consumption
                : int(0);
            // TDM-aware penalties (same slot-specific coefficients as objectiveFunction).
            int localPenalty = overConsumption    * _getALPHA(i) +
                               flexibilityViolation * _getBETA(i)  +
                               unusedRenewable    * _getGAMMA(i);

            int globalAdjustment = 0;
            if (globalPlan.length == len) {
                int globalValue = globalPlan[i];
                int deviation = consumption - globalValue;
                int absDeviation = deviation >= 0 ? deviation : -deviation;
                int threshold = globalValue != 0 ? globalValue / 10 : int(0);
                if (absDeviation > threshold) {
                    if (deviation > 0) {
                        globalAdjustment =
                            (absDeviation - threshold) *
                            PENALTY_GLOBAL;
                    } else {
                        globalAdjustment = -((absDeviation - threshold) *
                            REDEEM_GLOBAL);
                    }
                }
            }
            int hourCost = localCost + localPenalty + globalAdjustment;
            totalCost += hourCost;
        }
        return totalCost;
    }
    function getPersonalBestPosition() public view returns (int[] memory) {
        return personalBestPosition;
    }

    // Convenience function: returnează costul calculat cu snapshot-ul
    function getFrozenCost() public view returns (int) {
        return objectiveFunctionFrozen(personalBestPosition);
    }

    function getPosition() public view returns (int[] memory) {
        int[] memory copy = new int[](position.length);
        for (uint i = 0; i < position.length; i++) {
            copy[i] = position[i];
        }
        return copy;
    }

    function getTariff() public view returns (int[] memory) {
        return tariff;
    }

    function getCapacity() public view returns (uint[] memory) {
        return capacity;
    }

    function getBatteryCharge() public view returns (uint[] memory) {
        return batteryCharge;
    }

    function getUsedRenewablePlan() external view returns (int256[] memory) {
        int256[] memory result = new int256[](position.length);
        for (uint i = 0; i < position.length; i++) {
            result[i] = usedRenewablePerHour[i];
        }
        return result;
    }

    function getBatteryCapacity() public view returns (uint[] memory) {
        return batteryCapacity;
    }

    function getRenewableGeneration() public view returns (uint[] memory) {
        return renewableGeneration;
    }

    function getFlexibilityAbove() public view returns (uint[] memory) {
        return flexibilityAbove;
    }

    function getFlexibilityBelow() public view returns (uint[] memory) {
        return flexibilityBelow;
    }

    struct HourlyBreakdown {
        int consumption;
        bool isInjection;
        uint fromRenewable;
        uint fromBattery;
        uint fromGrid;
        int globalTarget;
        int deviationFromGlobal;
    }

    function getFlexibleLoad() public view returns (uint[] memory) {
        return flexibleLoad;
    }

    function getFrozenEnergyBreakdown()
        public
        view
        returns (HourlyBreakdown[] memory)
    {
        uint len = personalBestPosition.length;
        HourlyBreakdown[] memory breakdown = new HourlyBreakdown[](len);
        int[] memory globalPlan = globalContract.getBestGlobalPlan();

        for (uint i = 0; i < len; i++) {
            int cons = personalBestPosition[i];
            HourlyBreakdown memory hour;

            hour.consumption = cons;
            hour.isInjection = cons < 0;
            hour.globalTarget = globalPlan.length == len
                ? globalPlan[i]
                : int(0);
            hour.deviationFromGlobal = cons - hour.globalTarget;

            if (cons > 0) {
                uint remaining = uint(cons);
                uint renew = frozenRenewableGeneration[i];
                uint battery = frozenBatteryCharge[i];

                if (renew >= remaining) {
                    hour.fromRenewable = remaining;
                    remaining = 0;
                } else {
                    hour.fromRenewable = renew;
                    remaining -= renew;
                }

                if (battery >= remaining) {
                    hour.fromBattery = remaining;
                    remaining = 0;
                } else {
                    hour.fromBattery = battery;
                    remaining -= battery;
                }

                hour.fromGrid = remaining;
            }

            breakdown[i] = hour;
        }

        return breakdown;
    }
}

contracts/TestContract.sol.content:
// SPDX-License-Identifier: MIT

pragma solidity ^0.8.10;

import "./DateTime.sol";

contract TestContract{
    uint256 private number;

    constructor(uint256 _number) {
        number = _number;
    }

    function setNumber(uint256 _number) public returns (uint256){
        if(_number % 2 == 0) {
            number += _number * 2;
        } else {
            number += _number;
        }
        return number;
    }

    function getNumber() public view returns(uint256){
        return number;
    }

}

